contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint minSum, uint depositAmt, uint collectAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        require(address(this).balance >= depositAmt);
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        uint senderBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractBefore = address(c).balance;

        require(senderBefore < c.MinSum());

        bool reverted;
        c.Collect(collectAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint senderAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractAfter = address(c).balance;

        assert(!reverted && senderAfter == senderBefore && contractAfter == contractBefore);
    }

    receive() external payable {}
}

