pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 minSum, uint256 depositAmt, uint256 collectAmt) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        vm.assume(address(this).balance >= depositAmt);
        try c.Deposit{value: depositAmt}() {} catch { return; }
        uint256 senderBefore;
        try c.balances(address(this)) returns (uint256 __r) { senderBefore = __r; } catch { return; }
        uint contractBefore = address(c).balance;
        vm.assume(senderBefore < c.MinSum());
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 senderAfter;
        try c.balances(address(this)) returns (uint256 __r) { senderAfter = __r; } catch { return; }
        uint contractAfter = address(c).balance;
        assertTrue(!reverted && senderAfter == senderBefore && contractAfter == contractBefore);
    }

    function testFuzz_run(uint256 minSum, uint256 depositAmt, uint256 collectAmt) public {
        _run(minSum, depositAmt, collectAmt);
    }

    receive() external payable {}
}
